-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.wilson_low(k bigint, n bigint)
 RETURNS double precision
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case when n > 0 then greatest(0, (k::float8 / n + 1.9208 / n
           - 1.96 * sqrt((k::float8 / n) * (1 - k::float8 / n) / n + 0.9604 / (n::float8 * n)))
           / (1 + 3.8416 / n)) end;
$function$;

grant execute on function public.wilson_low(k bigint, n bigint) to service_role;
